def closing(step, tail):
    """마지막 단계의 명령들 뒤에 붙일 HTML(구조 검사와 내 말로 되짚기) — 가이드가 명령 확인 문장으로 끝나지 않게 한다(코딩랩 머리말 · 가이드 P-5)."""
    return dict(step, body=step['body'] + tail)


